CREATE TABLE execution_supervisor_checkpoint_v1 (workspace_id TEXT NOT NULL REFERENCES workspace(workspace_id),work_item_id TEXT NOT NULL CHECK(length(CAST(work_item_id AS BLOB)) BETWEEN 1 AND 128),session_id TEXT NOT NULL CHECK(length(CAST(session_id AS BLOB)) BETWEEN 1 AND 128),capsule_digest TEXT NOT NULL CHECK(length(capsule_digest)=64 AND capsule_digest NOT GLOB '*[^0-9a-f]*'),queue_digest TEXT NOT NULL CHECK(length(queue_digest)=64 AND queue_digest NOT GLOB '*[^0-9a-f]*'),active_ordinal INTEGER NOT NULL CHECK(active_ordinal>=0),no_progress_batches INTEGER NOT NULL CHECK(no_progress_batches BETWEEN 0 AND 255),source_cache_hits INTEGER NOT NULL CHECK(source_cache_hits>=0),source_cache_misses INTEGER NOT NULL CHECK(source_cache_misses>=0),updated_event_seq INTEGER NOT NULL CHECK(updated_event_seq>=0),updated_at TEXT NOT NULL,PRIMARY KEY(workspace_id,work_item_id,session_id));
PRAGMA user_version=11;
